function local_coeffs(theta, j, e_max):
    roots <- [exp(i (j-2k) theta) for k in 0..j]
    series <- [1, 0, ..., 0]           // length e_max+1
    for z in roots:
        series <- convolve(series, [z^0, z^1, ..., z^{e_max}])  // multiply by 1/(1 - z x)
    return real_part(series)

function assemble(local, N):
    lam <- array of zeros; lam[1] <- 1
    for prime p with data local[p]:
        for e in 1 .. deg(local[p]):
            for base coprime to p with base * p^e <= N:
                lam[base * p^e] <- lam[base] * local[p][e]
    return lam

function count_sign_changes(coeffs, m, N):
    if m >= 4: indices <- 1..N
    elif m == 2: indices <- {n in 1..N : is_sum_of_two_squares(n)}
    prev <- 0; changes <- 0
    for n in indices (increasing):
        s <- sign(coeffs[n])
        if s == 0: continue
        if prev != 0 and s != prev: changes <- changes + 1
        prev <- s
    return changes

